    // Reuses `policy_precedence::overlap_is_no_less_restrictive` -- the SAME comparison the live overlay
    // already trusts for exactly this question -- rather than a second, parallel one. Partitioned, not
    // all-or-nothing: an ordinary reclassification legitimately carries many rules, and one bad rule must
    // not block the rest, exactly as the live overlay treats REPOSITORY_CONTRACT.paths rule by rule.
    let kernel_dir = crate::kernel_trust::trusted_root(p);
    let kernel_paths = crate::util::read_yaml(
        &kernel_dir.join("overlay-templates").join("REPOSITORY_CONTRACT.yaml"),
    )
    .ok()
    .and_then(|v| v.get("paths").and_then(|a| a.as_array().cloned()))
    .unwrap_or_default();
    // Fail closed, not fail open: an empty `kernel_paths` here (an unreadable or malformed kernel template)
    // would otherwise make every proposed rule pass the loop below vacuously -- no kernel rule to overlap,
    // so nothing to compare against. The kernel template genuinely carries dozens of rules; an empty result
    // means the baseline this validation needs could not be established, which must refuse the transaction,
    // not silently validate nothing.
    if kernel_paths.is_empty() {
        return Err(GovError::new(
            "ADOPTION_FLOOR_KERNEL_BASELINE_UNAVAILABLE",
            "reclassify_adoption_floor: the kernel template's own REPOSITORY_CONTRACT.yaml paths could not \
             be read (AR84-C2's validation has nothing to compare proposed rules against); refusing rather \
             than writing an unvalidated floor",
        ));
    }
    let (accepted, refused) =
        crate::policy_precedence::partition_floor_rules_against_kernel(&kernel_paths, &rules);
    seals.floor_rules_refused.extend(refused);
    crate::paths::write_project_adoption_floor(
        &p.root,
        &accepted,
        &seals.op_name(kind),
        Some(&seals.cit),
    )?;
    touched.push(crate::paths::PROJECT_ADOPTION_FLOOR_PATH.to_string());
}
